import{_ as t,C as c,o as d,c as i,j as o,a,E as n,a2 as l}from"./chunks/framework.DCaeQ2Kp.js";const f=JSON.parse('{"title":"打断 (barge-in)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/barge-in.md","filePath":"guide/barge-in.md"}'),s={name:"guide/barge-in.md"};function m(u,e,g,h,p,b){const r=c("DiagramFrame");return d(),i("div",null,[e[0]||(e[0]=o("h1",{id:"打断-barge-in",tabindex:"-1"},[a("打断 (barge-in) "),o("a",{class:"header-anchor",href:"#打断-barge-in","aria-label":'Permalink to "打断 (barge-in)"'},"​")],-1)),e[1]||(e[1]=o("p",null,[a("真打断是「像人」的关键——momo 说话中途你开口，她立刻停。"),o("strong",null,"三动作，顺序固定、幂等执行。")],-1)),n(r,{src:"barge-in.html",height:620}),e[2]||(e[2]=l('<h2 id="触发源" tabindex="-1">触发源 <a class="header-anchor" href="#触发源" aria-label="Permalink to &quot;触发源&quot;">​</a></h2><ul><li><code>vad_speech</code>：<code>Speaking</code>/<code>Thinking</code> 中 ASR 上报 <code>input.vad{speech_start}</code>，防抖 ≥<code>MOMO_BARGEIN_MIN_MS</code>（250ms）</li><li><code>user</code>：手动插话键 / PTT</li><li><code>system</code>：系统原因</li></ul><h2 id="三动作" tabindex="-1">三动作 <a class="header-anchor" href="#三动作" aria-label="Permalink to &quot;三动作&quot;">​</a></h2><ol><li><strong>停播</strong>：广播 <code>control.barge_in{applied:true}</code> → UI 清播放缓冲并回报 <code>played_seq</code>；orch 丢弃下行未发送部分</li><li><strong>取消上游</strong>：回合取消令牌触发——abort LLM HTTP 流（OpenAI 无取消语义，直接断）、清空 <code>sentence_q</code>、<code>control.cancel</code> 至 TTS(turn)/ASR(segment)</li><li><strong>已播入账</strong>：<code>played_seq</code> 前完整句以 assistant 消息入历史（<code>interrupted:true</code>）；在播句按已送音频估算前缀截断；未下发句丢弃</li></ol><h2 id="硬约束" tabindex="-1">硬约束 <a class="header-anchor" href="#硬约束" aria-label="Permalink to &quot;硬约束&quot;">​</a></h2><ul><li>同 <code>turn_id</code> 重复 barge_in 幂等，只执行一次</li><li><code>played_seq</code> 回报超时（500ms）按「已送出即已播」保守入账</li><li><strong>记账完成前不回 <code>Listening</code></strong>——保证模型「记得的」= 用户「听到的」</li><li>取消令牌不复用：新回合 = 新令牌</li></ul><h2 id="时序目标" tabindex="-1">时序目标 <a class="header-anchor" href="#时序目标" aria-label="Permalink to &quot;时序目标&quot;">​</a></h2><p>取消令牌 cancel 后各管线任务 &lt;50ms 退出（<code>select!</code> 监听子 token）；模型服务须 200ms 内停产出，迟到帧按 <code>seq</code>/<code>tag</code> 丢弃。</p><div class="info custom-block"><p class="custom-block-title">权威来源</p><p><a href="https://github.com/Momoyeyu/momo-docs/blob/master/01-architecture/runtime.md" target="_blank" rel="noreferrer">momo-docs/01-architecture/runtime.md</a> §2-3 · <a href="https://github.com/Momoyeyu/momo-docs/blob/master/01-architecture/protocol.md" target="_blank" rel="noreferrer">protocol.md</a> <code>control.barge_in</code>/<code>control.cancel</code>。</p></div>',9))])}const k=t(s,[["render",m]]);export{f as __pageData,k as default};
